// Matches http:// and https:// URLs only. Any other scheme (ftp, mailto,
// file, javascript, data, ...) or a misspelled prefix (htp://) will not match.
// `<` and `>` are excluded from the URL body so surrounding markup-like text
// is never absorbed into the href.
const URL_REGEX = /https?:\/\/[^\s<>]+/gi;

// Trailing punctuation that is commonly adjacent to, but not part of, a URL.
const TRAILING_PUNCTUATION = /[.,;:!?'"]+$/;

const countChar = (value: string, char: string): number =>
  value.split(char).length - 1;

// Removes punctuation that hugs a URL without being part of it: trailing
// periods/commas/etc. and unbalanced closing brackets/parens introduced by
// enclosing the URL, e.g. "(https://x.com)" or "[https://x.com]".
const trimTrailingPunctuation = (url: string): string => {
  let result = url;
  let changed = true;

  while (changed && result.length > 0) {
    changed = false;

    const punctuation = result.match(TRAILING_PUNCTUATION);
    if (punctuation) {
      result = result.slice(0, -punctuation[0].length);
      changed = true;
      continue;
    }

    if (
      result.endsWith(")") &&
      countChar(result, ")") > countChar(result, "(")
    ) {
      result = result.slice(0, -1);
      changed = true;
      continue;
    }

    if (
      result.endsWith("]") &&
      countChar(result, "]") > countChar(result, "[")
    ) {
      result = result.slice(0, -1);
      changed = true;
    }
  }

  return result;
};

const linkifyString = (text: string): React.ReactNode[] => {
  const nodes: React.ReactNode[] = [];
  let lastIndex = 0;
  let key = 0;
  let match: RegExpExecArray | null;

  URL_REGEX.lastIndex = 0;
  while ((match = URL_REGEX.exec(text)) !== null) {
    const raw = match[0];
    const url = trimTrailingPunctuation(raw);

    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }

    if (url.length > 0) {
      nodes.push(
        <a
          key={key++}
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="text-blue-600 underline break-all"
          onClick={(event) => event.stopPropagation()}
        >
          {url}
        </a>,
      );
    }

    // Punctuation stripped from the URL stays in the surrounding text.
    const suffix = raw.slice(url.length);
    if (suffix) {
      nodes.push(suffix);
    }

    lastIndex = match.index + raw.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
};

const LinkifyText = ({ children }: { children?: React.ReactNode }) => {
  if (children === null || children === undefined) {
    return <></>;
  }

  if (typeof children === "number") {
    return <>{String(children)}</>;
  }

  if (typeof children === "string") {
    // Plain text with no protocol prefix is rendered verbatim so the
    // container's innerHTML matches the input string exactly.
    if (!children.includes("http")) {
      return <>{children}</>;
    }

    return <>{linkifyString(children)}</>;
  }

  // Any other React node is rendered as-is.
  return <>{children}</>;
};

export default LinkifyText;
